import { Box, Typography, Stack, Divider, Chip } from '@mui/material';

const history = [
  { contract: 'สัญญา A', date: '2025-08-01', amount: '฿1,000', status: 'รอการยืนยัน' },
  { contract: 'สัญญา B', date: '2025-07-01', amount: '฿1,000', status: 'ยืนยันการชำระเงิน' },
];

export default function PaymentHistory() {
  return (
    <Box>
      <Typography variant="h6" gutterBottom>ประวัติการชำระเงิน</Typography>
      <Stack spacing={2}>
        {history.map((item, index) => (
          <Box
            key={index}
            sx={{
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
              p: 2,
            //   borderRadius: 2,
              backgroundColor: '#f9f9f9',
              boxShadow: 1,
            }}
          >
            <Box>
              <Typography variant="subtitle1">{item.contract}</Typography>
              <Typography variant="body2" color="text.secondary">{item.date}</Typography>
            </Box>
            <Box textAlign="right">
              <Typography variant="subtitle1">{item.amount}</Typography>
              <Chip
                label={item.status}
                color={item.status === 'ยืนยันการชำระเงิน' ? 'success' : 'warning'}
                size="small"
              />
            </Box>
          </Box>
        ))}
      </Stack>
      <Divider sx={{ mt: 4 }} />
    </Box>
  );
}
